USE inventory_supply_chain_db;


-- Example transactional history for dashboard charts and movement reports.
SELECT MOD(n-1,5)+1,MOD(n-1,20)+1,MOD(n-1,3)+1,MOD(n,12)+5,200+MOD(n*137,1100),(MOD(n,12)+5)*(200+MOD(n*137,1100)),IF(MOD(n,4)=0,'Pending','Paid'),DATE_SUB(CURDATE(),INTERVAL MOD(n*11,330) DAY) FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24) seq;
SELECT MOD(n-1,10)+1,MOD(n*7-1,20)+1,MOD(n,4)+1,350+MOD(n*173,1700),(MOD(n,4)+1)*(350+MOD(n*173,1700)),IF(MOD(n,5)=0,'Pending','Paid'),DATE_SUB(CURDATE(),INTERVAL MOD(n*7,300) DAY) FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13 UNION ALL SELECT 14 UNION ALL SELECT 15 UNION ALL SELECT 16 UNION ALL SELECT 17 UNION ALL SELECT 18 UNION ALL SELECT 19 UNION ALL SELECT 20 UNION ALL SELECT 21 UNION ALL SELECT 22 UNION ALL SELECT 23 UNION ALL SELECT 24 UNION ALL SELECT 25 UNION ALL SELECT 26 UNION ALL SELECT 27 UNION ALL SELECT 28 UNION ALL SELECT 29 UNION ALL SELECT 30 UNION ALL SELECT 31 UNION ALL SELECT 32 UNION ALL SELECT 33 UNION ALL SELECT 34 UNION ALL SELECT 35 UNION ALL SELECT 36) seq;
SELECT MOD(n-1,10)+1,MOD(n*3-1,20)+1,MOD(n,5)+1,(MOD(n,5)+1)*499,IF(MOD(n,3)=0,'Pending','Paid'),ELT(MOD(n-1,5)+1,'Pending','Processing','Shipped','Delivered','Cancelled'),DATE_SUB(CURDATE(),INTERVAL n*2 DAY) FROM (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12) nums;
SELECT product_id,warehouse_id,'Purchase',quantity,0,quantity,CONCAT('DEMO-PUR-',id),purchase_date FROM purchases;
SELECT s.product_id,p.warehouse_id,'Sale',s.quantity,p.quantity+s.quantity,p.quantity,CONCAT('DEMO-SAL-',s.id),s.sale_date FROM sales s JOIN products p ON p.id=s.product_id;



